test('path-bearing header lines must be the pull request paths and header lines cannot repeat', () => {
  const header = (...lines) => `${lines.join('\n')}\n${HUNK}\n`;
  const ok = ['diff --git a/src/a.js b/src/a.js', '--- a/src/a.js', '+++ b/src/a.js'];
