  assert.throws(() => verifyPatches({snapshot: snapshotOf(['src/a.js', 'modified', HUNK], ['src/b.js', 'modified', HUNK]),
    files: [live('src/a.js', 'modified', HUNK), live('src/b.js', 'modified')]}), /incomplete/);
